  ('draft-midnight-role-call',1,'The midnight role call','Invent a character who is definitely not you, agree a scene and a way out, then talk in character for ten minutes.','fantasy',3,2,1,30,'{"tags":["role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree the scene and the exit line."],"accessibility":["Text-only version works."],"safetyFlags":["An exit line ends the scene immediately, every time."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-slow-burn-sequence',1,'The slow-burn sequence','A three-step sequence written by both of you in advance, with every step individually opt-in and skippable.','touch',3,2,1,30,'{"tags":["sequence"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Write three steps; both initial each one."],"accessibility":["Any step can be replaced by a seated alternative."],"safetyFlags":["Ask before touch.","Skipping a step is not a failure."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-secret-menu-card',1,'The secret menu card','A private card of things you are curious about, sealed and opened only if both of you choose to.','fantasy',3,2,0,20,'{"tags":["writing"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Dictate into a shared document instead."],"safetyFlags":["Opening the card requires both of you, every time."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('slow-burn-stare',1,'The slow-burn stare','Count to five in silence and look at each other like you are deciding something. Whoever looks away first describes what they were thinking.','tease',1,1,0,5,'{"tags":["eye-contact","nerve"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Eyes closed and describing the voice works just as well."],"safetyFlags":["Naming a thought is not agreeing to it."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('whisper-the-menu',1,'Whisper the menu','Each of you whispers three things you would enjoy tonight, from the deeply sensible to the deeply silly. Nothing is ordered yet.','tease',2,1,0,10,'{"tags":["whisper","anticipation"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the three things and swap the page if whispering is hard."],"safetyFlags":["A whisper is a suggestion, never an instruction."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","main"]}','published',NULL,0,'public_preview'),
  ('the-countdown-kiss',1,'The countdown kiss','Count backwards from ten and stop at one, unless you both decide otherwise. Either of you may end the count at any number.','tease',2,2,0,10,'{"tags":["kiss","anticipation"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["A countdown to a held hand or a forehead touch counts the same."],"safetyFlags":["Ask before touch.","One word ends the count immediately."],"requiredOptIns":["touch"],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('three-compliments-and-a-secret',1,'Three compliments and a secret','Trade three specific compliments, then one small secret about wanting something. Passing on the secret is allowed and costs nothing.','tease',1,1,0,15,'{"tags":["compliments","nerve"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the secret and decide later whether to hand it over."],"safetyFlags":["A secret shared in this game stays in this room."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","main"]}','published',NULL,0,'public_preview'),
  ('the-elevator-pitch',1,'The elevator pitch','You have three floors to convince the other person to spend the evening exactly the way you want. They may counter-offer.','tease',1,2,0,10,'{"tags":["pitch","negotiation"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Sixty seconds of typing works, with a dramatic read-out."],"safetyFlags":["The counter-offer always wins if either of you prefers it."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('hold-the-look',1,'Hold the look','One minute of eye contact while one of you talks about something they love. No looking away, no scoring, no mercy.','tease',1,1,0,5,'{"tags":["eye-contact","attention"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["Sit side by side and hold hands instead of eyes."],"safetyFlags":["Looking away is allowed and never mentioned again."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('a-text-from-the-other-room',1,'A text from the other room','Leave the room and send one message you would not say out loud. The reply is optional; reading it aloud is mandatory.','tease',1,1,0,10,'{"tags":["texting","anticipation"],"environments":["home","hotel","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Dictate it to a speaker instead of typing."],"safetyFlags":["Delete the message together when the game ends."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('almost-but-not-quite',1,'Almost, but not quite','Take turns describing exactly what you would do next, then do none of it. The description is the entire game.','tease',2,2,0,10,'{"tags":["anticipation","talk"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Describe it in writing, one line at a time."],"safetyFlags":["Description is not permission; no follow-through is owed."],"requiredOptIns":["touch"],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('one-more-minute',1,'One more minute','Set a five-minute timer, spend it however you both agree, then decide together whether to buy one more minute. Three extensions maximum.','tease',2,2,1,15,'{"tags":["timer","negotiation"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["The minute can be a conversation, a song or a shoulder rub."],"safetyFlags":["Either of you can decline an extension without discussion."],"requiredOptIns":["touch"],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-rain-check',1,'The well-earned rain check','Name one idea you are genuinely interested in and one you are not ready for tonight. Write the second one down for a future evening.','tease',0,0,0,5,'{"tags":["future","boundaries"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Say it into a shared note instead."],"safetyFlags":["A rain check is not a promise, a deposit or a debt."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,0,'public_preview'),
  ('the-director-chair',1,'The director''s chair','One of you directs the next ten minutes: lighting, music, posture, where the other sits. Nothing physical unless you both say so.','power',1,2,0,15,'{"tags":["instructions","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":["phone-or-speaker"],"preparation":["Agree the stop word before the first instruction."],"accessibility":["Seated-only and voice-only directions are both legitimate."],"safetyFlags":["Agree a stop word before starting.","Directing ends the moment either of you says stop."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('switch-the-lamp',1,'Switch the lamp','Take turns in charge of one small thing each: the light, the music, the seating, the next drink. Swap after every choice.','power',1,2,0,15,'{"tags":["control","playful"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Every choice has a no-movement version."],"safetyFlags":["Either of you can hand control back at any moment."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup","main"]}','published',NULL,0,'public_preview'),
  ('the-ten-minute-rule',1,'The ten-minute rule','One of you proposes the plan for ten minutes; the other may only answer yes, no or a counter-offer. Then swap the roles entirely.','power',2,2,0,15,'{"tags":["negotiation","control"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Non-verbal answers can be cards reading yes, no and maybe."],"safetyFlags":["A no is final for the evening and never needs a reason."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
