  ('retell-the-first-date',1,'Retell the first date','Tell the story of your first date as if it were a film. The other person adds the parts you invented.','connection',0,0,0,20,'{"tags":["memory","story"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the opening scene and pass it over."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,0,'public_preview'),
  ('the-future-invitation',1,'The future invitation','Invite each other to something that does not exist yet: next spring, next year, a Tuesday you will not remember. Accept or negotiate.','connection',1,1,0,15,'{"tags":["future","playful"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Text the invitation and answer in person."],"safetyFlags":["An invitation is not a commitment until you both say yes."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","main"]}','published',NULL,0,'public_preview'),
