  ('the-mystery-accent',1,'The mystery accent','Pick an accent neither of you can do and commit completely for five minutes. Breaking character costs a compliment.','playful',1,2,1,15,'{"tags":["comedy","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Any voice, sign language flourish or typed persona counts."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
