  ('the-balcony-minute',1,'The balcony minute','Step outside, or open a window, and breathe in time together for sixty seconds. Nothing else happens. That is the point.','movement',0,0,1,5,'{"tags":["breathing","pause"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["Indoors with the window open is identical."],"safetyFlags":["Wrap up warm; no one is proving anything."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup","reconnect"]}','published',NULL,0,'public_preview'),
