  ('the-stretch-off',1,'The stretch-off','Take turns leading one stretch each and describing it like a wellness influencer. The worst description wins.','movement',1,1,1,15,'{"tags":["stretch","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Every stretch has a chair version."],"safetyFlags":["Never push into pain; this is comedy, not physio."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-freeze-frame',1,'The freeze frame','Dance until the music stops, then hold the most dramatic pose you can. Hold it until someone laughs.','movement',1,1,2,10,'{"tags":["dance","game"],"environments":["home","hotel","getaway","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Poses can be seated, and laughing first is a valid strategy."],"safetyFlags":["No pose that risks a fall."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-palm-reading',1,'The palm reading','Read each other''s palms with complete confidence and zero accuracy. Ask before taking a hand.','touch',1,1,0,10,'{"tags":["hands","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Read the back of the hand, or the sleeve."],"safetyFlags":["Ask before touch.","Stop on request without negotiating."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-tracing-game',1,'The tracing game','Trace one word on the other person''s back with a fingertip. They guess. Getting it wrong is funnier and encouraged.','touch',2,2,0,15,'{"tags":["touch","game"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree where touch is welcome before the first word."],"accessibility":["Trace on a palm or a forearm instead."],"safetyFlags":["Ask before touch.","Clothes stay on unless you both agree."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-hair-tie',1,'The ten-second hair tie','Tie the other person''s hair up badly, then fix it properly. Ten seconds each way, no commentary on the result.','touch',0,1,0,15,'{"tags":["care","silly"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Works on a scarf, a sleeve or nothing at all."],"safetyFlags":["Ask before touch.","Never pull or trap hair."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-wrist-pulse',1,'The wrist pulse','Hold the other person''s wrist and count their pulse out loud. They try to slow it down. Nobody wins.','touch',2,2,0,10,'{"tags":["closeness","slow"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["An ankle, a shoulder or a held hand works."],"safetyFlags":["Ask before touch.","Never press hard on the wrist."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-back-that-does-not-ache',1,'The back that does not ache','Two minutes of shoulder-blade attention for whoever wants it, over clothes, with a running commentary of complaints.','touch',0,1,0,15,'{"tags":["massage","care"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Seated, standing or lying down; pressure is chosen by the receiver."],"safetyFlags":["Ask before touch.","Never massage the spine directly."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,0,'public_preview'),
  ('the-cat-nap',1,'The cat nap','Lie down together for twenty minutes with no expectation beyond warmth and a blanket. Sleep is a valid outcome.','touch',0,0,0,20,'{"tags":["rest","cosy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["A shared sofa or two chairs and a footstool work."],"safetyFlags":["Nobody is owed anything for the cuddle."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-vanilla-test',1,'The vanilla test','Put something scented in the room and describe it in three words each. Whoever names it accurately wins nothing.','senses',1,1,0,10,'{"tags":["scent","game"],"environments":["home","hotel","getaway","private-other"],"supplies":["scent"],"preparation":["Check nobody has a sensitivity to the scent first."],"accessibility":["Describe the memory the scent suggests instead."],"safetyFlags":["Stop if a scent is unpleasant for either of you."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup","warm-up"]}','published',NULL,0,'public_preview'),
  ('the-mystery-texture',1,'The mystery texture','Blindfolded, the other person guides your hand to three textures and asks you to rank them. Revealing the order matters.','senses',1,1,0,10,'{"tags":["texture","blindfold"],"environments":["home","hotel","getaway","private-other"],"supplies":["silk","scarf"],"preparation":["Agree the blindfold and the stop signal first."],"accessibility":["Eyes closed and hands guided works identically."],"safetyFlags":["Ask before touch.","The blindfold comes off the moment you ask."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-blindfold-sip',1,'The blindfold sip','Three small tastes, one blindfold, and a solemn guess for each. Cheating is impossible and also the point.','senses',1,1,0,15,'{"tags":["taste","blindfold"],"environments":["home","hotel","getaway","private-other"],"supplies":["scarf","snack"],"preparation":["Check allergies and use small portions."],"accessibility":["Close your eyes and point instead of speaking."],"safetyFlags":["Never taste anything you are allergic to.","Sit up while eating."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-warm-towel',1,'The warm towel','Warm a towel, wrap it round the other person''s hands, and sit quietly for two minutes. Nobody explains why.','senses',0,1,0,15,'{"tags":["temperature","care"],"environments":["home","hotel","getaway","private-other"],"supplies":["towel"],"preparation":["Test the temperature on your own wrist first."],"accessibility":["A cool towel is an equally interesting experiment."],"safetyFlags":["Never use water hot enough to scald."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-metal-spoon',1,'The metal spoon','A cold spoon, a warm hand and a slow comparison of textures. Describe each one like a wine critic.','senses',1,1,0,10,'{"tags":["temperature","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":["ice"],"preparation":[],"accessibility":["Keep everything wrapped; no skin contact required."],"safetyFlags":["Never place ice directly on skin for long."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-hum-together',1,'The hum together','Pick a note and hold it together until someone cracks. Then pick a lower one, because that is funnier.','senses',0,1,0,10,'{"tags":["sound","silly"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Humming, tapping or lip-reading all work."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0,'public_preview'),
  ('the-character-lunch',1,'The character lunch','Invent two characters meeting for lunch: who they are, what they want, what they will never admit. Stay in character for twenty minutes.','fantasy',1,2,1,20,'{"tags":["role-play","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree one fact about each character before starting."],"accessibility":["Text-only scene with typed dialogue works."],"safetyFlags":["Every character has an exit line that ends the scene."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-scene-card',1,'The scene card','Write a single scene on a card: setting, two lines of dialogue and how it ends. Read it aloud, cast yourselves, and stop there.','fantasy',1,2,0,15,'{"tags":["writing","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Dictate the scene and let the other write it."],"safetyFlags":["Reading a scene is not agreeing to perform it."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-imaginary-hotel',1,'The imaginary hotel','Describe the hotel you would check into tonight: the room number, the view, what the concierge knows about you. Compare bookings.','fantasy',1,2,0,20,'{"tags":["hotel","imagination"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Describe it as a review rather than a story."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","main"]}','published',NULL,0,'public_preview'),
  ('the-fantasy-budget',1,'The fantasy budget','You have one hundred imaginary pounds and one evening. Allocate it line by line to the most extravagant evening you can justify.','fantasy',2,2,0,20,'{"tags":["budget","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Keep a running spoken total instead of writing."],"safetyFlags":["Nothing priced is being promised or purchased."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-maybe-menu',1,'The maybe menu','Each of you writes three things you are curious about but not certain of. Read them as maybes, with no answer required tonight.','fantasy',2,2,0,20,'{"tags":["curiosity","consent"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Type the list and read it aloud together."],"safetyFlags":["A maybe is a topic for discussion, never an approval.","Nobody has to respond to a maybe."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-secret-plot-twist',1,'The secret plot twist','Describe the evening so far as a film, then add a twist you would genuinely enjoy. The other person pitches an alternative ending.','fantasy',1,2,0,15,'{"tags":["story","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Pitch the twist as a three-line summary."],"safetyFlags":["A plot twist is fiction, not a request."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0,'public_preview'),
  ('the-notes-app',1,'The shared note','Open a note on one phone and type the things you want to remember about tonight. Delete it together in the morning, or keep it.','reconnect',0,0,0,10,'{"tags":["writing","memory"],"environments":["home","hotel","getaway","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Voice memo instead of typing."],"safetyFlags":["Decide together whether the note is kept."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-bragging-rights',1,'The bragging rights','Each of you brags about the other person to an imaginary audience of your friends. Be specific and slightly too much.','reconnect',1,1,0,10,'{"tags":["compliments","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Record it as a voice note and never send it."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-mini-debrief',1,'The two-minute debrief','Two minutes each: what worked, what did not, what you would want next time. No defending, no scoring, no homework.','reconnect',0,0,0,10,'{"tags":["debrief","care"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["Write your half and exchange pages."],"safetyFlags":["Feedback is an offer, not an instruction."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-last-song',1,'The last song','One track, on the sofa, lights low, no talking. When it ends the evening is officially closed and nobody owes an encore.','reconnect',0,0,0,10,'{"tags":["music","closing"],"environments":["home","hotel","getaway","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Read the lyrics together instead of playing it."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('the-blanket-vote',1,'The blanket vote','One vote each: blanket, snacks, or ten more minutes of conversation. Whichever wins, both of you get it.','reconnect',0,0,0,5,'{"tags":["cosy","vote"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["A thumbs up, a nod or a written vote all count."],"safetyFlags":["Nobody has to explain their vote."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0,'public_preview'),
  ('draft-slow-burn-handover',1,'The slow-burn handover','Agree who leads, agree the stop word, then hand over one decision at a time. Intensity is negotiated out loud before it happens.','power',3,2,1,45,'{"tags":["power","negotiation"],"environments":["home","hotel","getaway","private-other"],"supplies":["scarf"],"preparation":["Agree the stop word and the check-in interval in advance.","Both partners state one hard limit each, out loud."],"accessibility":["Voice-only and seated versions are valid scenes."],"safetyFlags":["Stop word ends everything immediately, every time.","Reading this draft is not permission for anything in it."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-blindfold-hour',1,'The blindfold hour','A sensory scene built on anticipation rather than acts: sound, temperature and texture, with the blindfold removed on request.','senses',3,2,1,60,'{"tags":["sensory","trust"],"environments":["home","hotel","getaway","private-other"],"supplies":["scarf","ice"],"preparation":["Lay out every item where both of you can reach it."],"accessibility":["No-touch version keeps every texture on the table."],"safetyFlags":["Ask before touch.","Nothing goes near the face, throat or eyes.","The blindfold comes off instantly on request."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-roleplay-scene',1,'The agreed scene','Write the scene together first: characters, setting, one thing that will happen and the exit line. Perform only what is written.','fantasy',3,2,1,45,'{"tags":["role-play","consent"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":["Both write the scene and sign the same page."],"accessibility":["Text-only performance is a complete version."],"safetyFlags":["The exit line ends the scene instantly.","Anything not written is not in the scene."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-restraint-protocol',1,'The restraint protocol','A written protocol for consensual restraint: materials, check-ins, release and aftercare, agreed and rehearsed before anything happens.','power',3,2,1,60,'{"tags":["restraint","safety"],"environments":["home","hotel","getaway","private-other"],"supplies":["scarf"],"preparation":["Write the protocol together and rehearse the release.","Agree that either partner can end it without a reason."],"accessibility":["Seated and fully mobile versions are the only approved starting point."],"safetyFlags":["Never restrain the neck, chest or airway.","Never leave a restrained person alone.","Keep safety scissors within reach.","This draft is not authorised for use and has not passed specialist review."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-whispered-orders',1,'The whispered orders','A verbal-only power game: quiet, specific instructions that either partner may decline at any point without ending the evening.','power',3,2,0,30,'{"tags":["verbal","power"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree which topics are in scope tonight."],"accessibility":["Written notes or signed commands work."],"safetyFlags":["Declining an instruction is always allowed and never penalised.","Stop is a complete sentence."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-mirror-lesson',1,'The mirror lesson','A fantasy-forward scene about being watched and instructed, performed entirely through words and posture, with an exit line agreed first.','fantasy',3,2,0,30,'{"tags":["mirror","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":["mirror"],"preparation":["Agree the exit line and whether the mirror stays covered."],"accessibility":["Audio-description version requires no mirror at all."],"safetyFlags":["No body commentary that either partner has not invited.","The exit line ends the scene immediately."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-curiosity-inventory',1,'The curiosity inventory','Two private lists of curiosities, sealed and traded only if both choose. No list is a request and no answer is expected tonight.','fantasy',3,2,0,30,'{"tags":["curiosity","writing"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":["Agree before writing that both may keep their list sealed."],"accessibility":["Type the list and decide together whether to exchange."],"safetyFlags":["A list is not consent, a promise or a request.","Either list may stay sealed indefinitely."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-temperature-game',1,'The temperature game','A warm-and-cold sensory sequence with strict safety limits, a running check-in, and an immediate stop signal held by the receiving partner.','senses',3,2,1,45,'{"tags":["temperature","sensory"],"environments":["home","hotel","getaway","private-other"],"supplies":["ice","towel"],"preparation":["Test every temperature on your own skin first."],"accessibility":["Wrapped and no-skin-contact versions are equivalent."],"safetyFlags":["Never place ice directly on skin for more than a few seconds.","Nothing hot enough to scald is ever used.","The receiving partner holds the stop signal at all times."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-brat-hour',1,'The brat hour','A playful defiance scene about saying no with a grin. Every tease is invited, revocable and ended instantly by either partner.','power',3,2,1,45,'{"tags":["playful","power"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree what teasing is welcome and what is off-limits."],"accessibility":["All defiance can be verbal or written."],"safetyFlags":["Real discomfort ends the scene and is not part of it.","Nothing is owed because someone was teased."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted'),
  ('draft-aftercare-ritual',1,'The aftercare ritual','A deliberate wind-down after intensity: water, blanket, quiet, and an honest two-question check-in with no fixing required.','reconnect',3,1,0,30,'{"tags":["aftercare","care"],"environments":["home","hotel","getaway","private-other"],"supplies":["towel"],"preparation":["Agree the two check-in questions before the scene, not after."],"accessibility":["Works over text if talking is too much."],"safetyFlags":["Asking for care is never a mood-killer.","Aftercare is not a reward and cannot be withheld."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','draft',NULL,0,'restricted'),
  ('draft-scene-notebook',1,'The scene notebook','Keep a shared notebook of scenes you may want later, with a review date. Writing it down never schedules it.','fantasy',3,2,0,30,'{"tags":["writing","future"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":["Agree where the notebook is kept and who else can read it."],"accessibility":["An encrypted note both partners can open is equivalent."],"safetyFlags":["An unused scene is not a broken promise.","Both partners may remove a page without discussion."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0,'restricted');

INSERT INTO wheels(id,version,title,selection_policy,status,tagline,description,draw_mode,shortlist_size) VALUES
  ('misfortune',1,'The Wheel of Misfortune','uniform','published','Spin responsibly. Misbehave consensually.','The full menu. Every reviewed non-explicit idea in the house.','single',8),
  ('foreplay',1,'The Wheel of Foreplay','uniform','published','All the anticipation, none of the rush.','A slower wheel: flirting, teasing, atmosphere and warm-ups. Best with a mild or medium ceiling.','single',8),
  ('double-trouble',1,'Double Trouble','uniform','published','Two ideas, one evening, no leftovers.','The house deals a compatible pair that fits your time budget, so the evening has a first act and a second.','pair',8),
  ('dealers-choice',1,'Dealer''s Choice','uniform','published','You keep the boundaries. The house picks the category.','One category is chosen for you from the ideas that already fit your rules, then the wheel draws inside it.','category',8),
  ('chemistry-preview',1,'Good Chemistry','uniform','draft','','','single',8)
ON CONFLICT(id,version) DO UPDATE SET title = excluded.title,
  selection_policy = excluded.selection_policy, status = excluded.status,
  tagline = excluded.tagline, description = excluded.description,
  draw_mode = excluded.draw_mode, shortlist_size = excluded.shortlist_size;

