INSERT OR IGNORE INTO recipe_templates(id,version,title,metadata_json,status,pack_id,access_tier,public_preview) VALUES
  ('slow-cooker',1,'The Slow Cooker','{"subtitle":"A long, low evening with absolutely no hurry in it","intro":"Nothing here needs to happen quickly. You set the room, you eat something, you talk longer than you planned, and the whole thing simmers until it is ready.","mood":"romantic","heatBand":[0,2],"experimentationBand":[0,2],"minimumMinutes":90,"maximumMinutes":240,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":10,"supplies":["phone-or-speaker"],"preparation":["Phones face down and out of reach.","One playlist, chosen by whoever is feeling smug about their taste.","Something to drink that is not a performance."],"closing":"End on the sofa, not on a schedule. The evening is done when you both say it is.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('five-alarm-chili',1,'Five-Alarm Chili','{"subtitle":"Short, hot and best attempted with a glass of water nearby","intro":"A spicy recipe with a real ceiling, a stop word and a cold drink. It is intense on purpose and it ends when one of you says so — not when a timer does.","mood":"adventurous","heatBand":[2,2],"experimentationBand":[1,2],"minimumMinutes":60,"maximumMinutes":120,"environments":["home","hotel","private-other"],"preparationMinutes":5,"supplies":[],"preparation":["Agree a stop word before the first course, not during it.","Water on the table, phones in another room."],"closing":"Cool down together. Water, blanket, no scoring.","requiredOptIns":["senses","touch"]}','published',NULL,'public_preview',1),
  ('breakfast-in-bed',1,'Breakfast in Bed','{"subtitle":"Because the best mornings start the night before","intro":"A gentle, low-energy recipe for a weekend with nowhere to be. Snacks, old stories and the good kind of laziness — served without a single alarm.","mood":"romantic","heatBand":[0,1],"experimentationBand":[0,2],"minimumMinutes":60,"maximumMinutes":240,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":10,"supplies":["snack"],"preparation":["Bring the snacks to the room before you get comfortable.","Curtains half open, lights low, no notifications."],"closing":"Stay in bed until the conversation runs out. That is the whole recipe.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('leftovers-can-be-delicious',1,'Leftovers Can Be Delicious','{"subtitle":"No shopping, no planning, no excuses","intro":"Built entirely from what is already in the house: a phone, a sofa, whatever is in the fridge and two people who cannot be bothered to go out. Low effort, high return.","mood":"playful","heatBand":[0,1],"experimentationBand":[0,2],"minimumMinutes":10,"maximumMinutes":120,"environments":["home","private-other"],"preparationMinutes":5,"supplies":[],"preparation":["Clear the coffee table and put the phones in a drawer.","Nothing needs buying. That is a rule, not a suggestion."],"closing":"Vote on the last thing you do together, then actually do it.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('full-meal-deal',1,'The Full Meal Deal','{"subtitle":"Six courses, one evening, absolutely no doggy bag","intro":"The long one. Characters get invented, scenes get written and a surprising amount of it is spent laughing at your own material. Set aside a real evening for this.","mood":"adventurous","heatBand":[1,2],"experimentationBand":[2,2],"minimumMinutes":120,"maximumMinutes":240,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":15,"supplies":["pen-paper"],"preparation":["Paper and two pens, because someone will insist on writing the good lines down.","One agreed exit line that ends any scene immediately."],"closing":"Debrief gently. The best bits usually happened in the middle.","requiredOptIns":["fantasy"]}','published',NULL,'public_preview',1),
  ('midnight-snack',1,'The Midnight Snack','{"subtitle":"Small portions, strong flavours, no regrets","intro":"Thirty minutes, one bite at a time. A late evening recipe for people who want something tasty without committing to a whole menu.","mood":"playful","heatBand":[1,2],"experimentationBand":[0,2],"minimumMinutes":30,"maximumMinutes":60,"environments":["home","hotel","private-other"],"preparationMinutes":0,"supplies":["snack"],"preparation":["A plate of something small, in reach of the sofa.","No screens except the one playing music."],"closing":"Finish on one sentence each and leave the plates until morning.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('hotel-tasting-menu',1,'The Hotel Tasting Menu','{"subtitle":"Room service energy, even if you are only away for one night","intro":"Written for a hotel or a getaway: robes, terrible lighting and the pleasant feeling of not having to tidy anything up. Small courses, generous pacing.","mood":"romantic","heatBand":[1,2],"experimentationBand":[1,2],"minimumMinutes":60,"maximumMinutes":240,"environments":["hotel","getaway"],"preparationMinutes":5,"supplies":["phone-or-speaker"],"preparation":["Unpack properly, even if it is one night.","Find the good lamp in the room and turn off the other one."],"closing":"Late checkout is a state of mind. Do not rush the morning either.","requiredOptIns":["touch"]}','published',NULL,'public_preview',1),
  ('ten-minute-tapas',1,'The Ten-Minute Tapas','{"subtitle":"A small plate of an evening, served immediately","intro":"Two tiny courses and no preparation whatsoever. For the nights when you have ten minutes, one sofa and a willingness to be a little ridiculous.","mood":"romantic","heatBand":[0,1],"experimentationBand":[0,1],"minimumMinutes":10,"maximumMinutes":30,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":0,"supplies":[],"preparation":["Nothing. That is the point."],"closing":"If it goes well, order a second plate. There is no third.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('potluck-surprise',1,'The Potluck Surprise','{"subtitle":"Everyone brings something and nobody admits what","intro":"A chaotic, generous recipe built on sealed envelopes, paper passes and one accent nobody can sustain. Best played with a straight face and no competitive streak whatsoever.","mood":"playful","heatBand":[0,2],"experimentationBand":[1,2],"minimumMinutes":90,"maximumMinutes":240,"environments":["home","hotel","private-other"],"preparationMinutes":5,"supplies":["pen-paper"],"preparation":["Tear paper passes before the first round.","Agree that a pass is a complete answer and needs no explanation."],"closing":"Nobody cleans up alone. That is the real potluck rule.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('sunday-brunch',1,'Sunday Brunch, No Reservations','{"subtitle":"Slow food for people with nothing to prove","intro":"A daytime recipe: gentle, seated and entirely uninterested in impressing anyone. The snack board is the main event and the conversation does the rest.","mood":"romantic","heatBand":[0,1],"experimentationBand":[0,1],"minimumMinutes":60,"maximumMinutes":120,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":10,"supplies":["snack"],"preparation":["Assemble something that looks like brunch, however loosely."],"closing":"Leave the dishes. Nobody is grading the afternoon.","requiredOptIns":[]}','published',NULL,'public_preview',1),
  ('dessert-first',1,'Dessert First','{"subtitle":"Sugar, salt, ice and a very slow spoon","intro":"A senses-first recipe where the sweet course arrives before anything sensible. Textures, temperatures and one terrible wine-critic voice you will both commit to.","mood":"playful","heatBand":[1,2],"experimentationBand":[1,2],"minimumMinutes":60,"maximumMinutes":120,"environments":["home","hotel","private-other"],"preparationMinutes":5,"supplies":[],"preparation":["Gather three safe textures or tastes before starting.","Agree the stop word, especially for temperature play."],"closing":"Warm towels, no commentary, lights low.","requiredOptIns":["senses"]}','published',NULL,'public_preview',1),
  ('chefs-table',1,'The Chef''s Table','{"subtitle":"One of you wears the hat. Both of you keep the stop word.","intro":"A consensual power-exchange recipe built on negotiation rather than surprise: written menus, crossed-out lines and a stop word that is always live. Nothing physical happens without a separate yes.","mood":"adventurous","heatBand":[2,2],"experimentationBand":[2,2],"minimumMinutes":90,"maximumMinutes":240,"environments":["home","hotel","getaway","private-other"],"preparationMinutes":10,"supplies":["pen-paper"],"preparation":["Both write a small menu and cross out anything you are not offering.","Agree the stop word, the check-in and how the evening ends."],"closing":"Aftercare is not optional. Water, blanket, two honest questions.","requiredOptIns":["power","fantasy"]}','published',NULL,'public_preview',1);

INSERT OR IGNORE INTO recipe_steps(recipe_id,recipe_version,position,phase,activity_id,activity_version,slot,optional,guidance,alternatives_json,max_minutes) VALUES
  ('slow-cooker',1,0,'setup','set-the-scene-in-five',1,'preparation',0,'Set the room before anyone is allowed to be interesting.','[{"id":"change-the-lighting","version":1},{"id":"the-arrival-ritual","version":1}]',10),
  ('slow-cooker',1,1,'setup','midnight-snack-plate',1,'atmosphere',0,'Put something on a plate that looks like it was planned.','[{"id":"the-snack-board","version":1}]',20),
  ('slow-cooker',1,2,'warm-up','twenty-questions-flirty',1,'warm-up',0,'Start with nonsense questions rather than sincere ones.','[{"id":"the-elevator-pitch","version":1},{"id":"hold-the-look","version":1}]',20),
